// Board symmetries for the symmetric-puzzle hunters. A symmetry is a permutation of the n*n cells; a
// symmetry class is a group of them (generated by a few), and its orbits partition the cells.
// Because tiles may be placed in every orientation, a puzzle whose blocked cells are symmetric and which
// has ONE solution must have a symmetric solution.
export const SYMMETRIES = {
  rot180:  { label: '180° rotation',                gens: [(r, c, n) => [n - 1 - r, n - 1 - c]] },
  rot90:   { label: '90° rotation',                 gens: [(r, c, n) => [c, n - 1 - r]] },
  mirror:  { label: 'mirror (left-right)',          gens: [(r, c, n) => [r, n - 1 - c]] },
  diag:    { label: 'mirror (diagonal)',            gens: [(r, c, n) => [c, r]] },
  axes:    { label: 'both mirrors (left-right and up-down)', gens: [(r, c, n) => [r, n - 1 - c], (r, c, n) => [n - 1 - r, c]] },
  diags:   { label: 'both diagonal mirrors',        gens: [(r, c, n) => [c, r], (r, c, n) => [n - 1 - c, n - 1 - r]] },
  full:    { label: 'rotation and mirror (all 8)',  gens: [(r, c, n) => [c, n - 1 - r], (r, c, n) => [r, n - 1 - c]] },
};

// Orbits of the cells of an n x n board under a symmetry class: an array of arrays of cell indices.
export function orbits(sym, n) {
  const gens = SYMMETRIES[sym].gens;
  const seen = new Int8Array(n * n), out = [];
  for (let i = 0; i < n * n; i++) {
    if (seen[i]) continue;
    const orbit = [], stack = [i];
    seen[i] = 1;
    while (stack.length) {
      const a = stack.pop();
      orbit.push(a);
      const r = Math.floor(a / n), c = a % n;
      for (const g of gens) {
        const [rr, cc] = g(r, c, n), b = rr * n + cc;
        if (!seen[b]) { seen[b] = 1; stack.push(b); }
      }
    }
    out.push(orbit.sort((x, y) => x - y));
  }
  return out;
}

// Is a per-cell string (grid or solution labels mapped through `same`) invariant under the class?
export function isSymmetricGrid(sym, n, grid) {
  const gens = SYMMETRIES[sym].gens;
  for (let i = 0; i < n * n; i++) {
    const r = Math.floor(i / n), c = i % n;
    for (const g of gens) { const [rr, cc] = g(r, c, n); if (grid[rr * n + cc] !== grid[i]) return false; }
  }
  return true;
}

// The cell maps of every element of the group (for transforming clue edges), as arrays cell -> cell.
export function groupMaps(sym, n) {
  const gens = SYMMETRIES[sym].gens;
  const id = Array.from({ length: n * n }, (_, i) => i);
  const key = m => m.join(',');
  const seen = new Map([[key(id), id]]), queue = [id];
  while (queue.length) {
    const m = queue.pop();
    for (const g of gens) {
      const next = m.map(i => { const [rr, cc] = g(Math.floor(i / n), i % n, n); return rr * n + cc; });
      if (!seen.has(key(next))) { seen.set(key(next), next); queue.push(next); }
    }
  }
  return [...seen.values()];
}
